const reviewed = '2026-11-02';
const src = {
  outlook: ['Microsoft Support', 'https://support.microsoft.com/outlook'],
  teams: ['Microsoft Support', 'https://support.microsoft.com/teams'],
  windows: ['Microsoft Support', 'https://support.microsoft.com/windows'],
  m365: ['Microsoft Support', 'https://support.microsoft.com/microsoft-365'],
  onedrive: ['Microsoft Support', 'https://support.microsoft.com/onedrive'],
  sharepoint: ['Microsoft Support', 'https://support.microsoft.com/sharepoint'],
  mac: ['Apple Support', 'https://support.apple.com/mac'],
  iphone: ['Apple Support', 'https://support.apple.com/iphone'],
  chrome: ['Google Chrome Help', 'https://support.google.com/chrome'],
  zoom: ['Zoom Support', 'https://support.zoom.com/']
};
const productSource = { Outlook: 'outlook', Teams: 'teams', Windows: 'windows', macOS: 'mac', iOS: 'iphone', OneDrive: 'onedrive', SharePoint: 'sharepoint', Zoom: 'zoom', Mail: 'outlook', Account: 'm365', Browser: 'chrome', Security: 'm365', Accessibility: 'windows', General: 'm365', Printer: 'windows', Scanner: 'windows', Display: 'windows', Headset: 'windows', Phone: 'iphone', Device: 'windows', 'Wi-Fi': 'windows', VPN: 'windows', 'Remote desktop': 'windows', Word: 'm365', Excel: 'm365', PowerPoint: 'm365', PDF: 'm365' };
function topic(slug, title, titleEn, category, product, os, keywords, keywordsEn, body, bodyEn, source, status = 'reviewed', handover = false) {
  const key = source || productSource[product] || (os === 'macOS' ? 'mac' : os === 'Windows' ? 'windows' : 'm365');
  const [source_name, source_url] = src[key];
  if (body.length <= 80 || bodyEn.length <= 80) throw new Error(`Short guidance: ${title}`);
  return { slug, title, title_en: titleEn, category, product, os, keywords, keywords_en: keywordsEn, body, body_en: bodyEn, handover, source_name, source_url, reviewed_at: reviewed, review_status: status };
}
export const extraKnowledge = [
  topic('outlook-calendar-missing', 'اجتماع لا يظهر في تقويم Outlook', 'An Outlook meeting is missing from the calendar', 'email', 'Outlook', '', 'تقويم outlook اجتماع موعد مش ظاهر calendar missing', 'outlook calendar meeting missing appointment', 'تحقق من أنك داخل تقويم حساب العمل، لا تقويم شخصي. ابحث عن الاجتماع بعنوانه أو باسم المنظّم، وراجع مجلد العناصر المحذوفة دون حذف شيء آخر. لا تنشئ دعوة جديدة بدل المفقودة إذا كان الاجتماع لشخص آخر. إذا بقي غائبًا بعد التحديث، سجّل وقت الدعوة واسم المنظّم واطلب الدعم.', 'Check that you are in the work calendar, not a personal one. Search by the subject or organizer and look in Deleted Items without deleting anything else. Do not create a replacement invitation for a meeting you do not own. If it is still missing, record the invite time and organizer and ask support.'),
  topic('outlook-invite-not-delivered', 'دعوة اجتماع Outlook لا تصل إلى المدعوين', 'An Outlook meeting invitation does not reach attendees', 'email', 'Outlook', '', 'دعوة اجتماع outlook لم تصل المدعوين invite attendees', 'outlook invitation attendees not received', 'أرسل الدعوة إلى عنوان تعرفه أولًا للتحقق. راجع قائمة المدعوين المطلوبة والاختيارية، ولا تفترض أن الغرفة قبلت الدعوة. لا تعِد الإرسال مرات كثيرة. إذا وصل الاختبار ولم تصل الدعوة للزميل، سجّل عنوانه ووقت الإرسال لفريق الدعم دون مشاركة تفاصيل الاجتماع الحساسة.', 'Send a test invitation to an address you know. Review required and optional attendees, and do not assume a room accepted. Do not resend many times. If the test arrives and a colleague does not receive it, give support the address and time without sensitive meeting details.'),
  topic('outlook-room-conflict', 'تعارض حجز غرفة اجتماعات', 'A meeting room shows a booking conflict', 'email', 'Outlook', '', 'غرفة اجتماعات محجوزة تعارض room booking conflict', 'meeting room booked conflict reservation', 'راجع وقت الغرفة في التقويم قبل اعتماد موعد آخر. لا تحذف حجز زميل. اختر غرفة أخرى ظاهرة كمتاحة أو اطلب من منظّم الحجز الحالي التنسيق. إذا ظهرت الغرفة محجوزة وهي فارغة فعليًا، سجّل اسم الغرفة والوقت واطلب من الدعم مراجعة التقويم.', 'Check the room time on the calendar before booking another slot. Do not delete a colleague’s booking. Choose another room that shows as free, or ask the current organizer to coordinate. If the room looks booked but is actually empty, record its name and the time for support.'),
  topic('outlook-search-misses', 'البحث في Outlook لا يجد رسالة موجودة', 'Outlook search does not find a message you know exists', 'email', 'Outlook', '', 'بحث outlook لا يجد رسالة search missing mail', 'outlook search cannot find message', 'ابحث بعنوان مختصر أو باسم المرسل داخل مجلد صندوق الوارد ثم المجلدات الأخرى. تحقق أنك تبحث في صندوق حساب العمل. لا تحذف الفهرس أو تعِد بناء البحث بنفسك. إذا ظهرت الرسالة عند التصفح واختفت من البحث، اذكر كلمة البحث ومجلدها للدعم.', 'Search by a short subject or the sender in Inbox, then in other folders. Confirm you are searching the work account. Do not delete or rebuild the search index yourself. If you can browse to the message but search misses it, tell support the term and folder.'),
  topic('outlook-rules-moved', 'قواعد Outlook تنقل الرسائل إلى مجلد غير متوقع', 'Outlook rules move messages to an unexpected folder', 'email', 'Outlook', '', 'قواعد outlook نقل رسائل مجلد rules folder', 'outlook rules moved messages folder', 'ابحث عن الرسالة في المجلدات قبل افتراض فقدها. راجع القواعد الظاهرة في إعدادات البريد دون حذفها إذا لم تكن أنت من أنشأها. لا تعطّل كل القواعد دفعة واحدة. إذا تغيّرت القواعد دون علمك، توقّف وأبلغ الدعم لأن ذلك قد يكون حادثًا أمنيًا.', 'Look through folders before assuming the message is lost. Review the rules you can see, and do not delete a rule you did not create. Do not turn off every rule at once. If rules changed without your knowledge, stop and tell support because that may be a security incident.', 'outlook', 'reviewed', true),
  topic('outlook-blocked-attachment', 'Outlook يمنع فتح مرفق', 'Outlook blocks an attachment', 'email', 'Outlook', '', 'مرفق محظور outlook blocked attachment', 'outlook blocked attachment cannot open', 'لا تعِد تسمية الملف لتتجاوز المنع ولا تطلب من المرسل تغيير الامتداد فقط. تأكد أن المرسل معروف وأن الملف متوقع. استخدم وسيلة مشاركة الملفات المعتمدة إذا كان الملف مشروعًا. إذا كان المرفق غير متوقع فتوقف وأبلغ الأمن.', 'Do not rename the file to bypass the block, and do not ask the sender only to change the extension. Confirm the sender is known and the file was expected. Use the approved file-sharing method for a work file. If the attachment was unexpected, stop and tell security.', 'outlook', 'reviewed', true),
  topic('outlook-web-vs-desktop', 'البريد يعمل في الويب ولا يعمل في تطبيق Outlook', 'Mail works on the web but not in the Outlook app', 'email', 'Outlook', '', 'اوتلوك ويب يعمل التطبيق لا outlook web app', 'outlook on the web works desktop app does not', 'حدد هل الحساب نفسه يفتح في بريد الويب الرسمي. لا تحذف ملف البيانات المحلي ولا تنشئ ملف تعريف جديد بنفسك؛ مسار القوائم يختلف بين Outlook الجديد والتقليدي ويحتاج مراجعة. سجّل هل الإرسال أو الاستقبال أو كلاهما متوقف في التطبيق فقط.', 'Note whether the same account opens in the official web mailbox. Do not delete the local data file or create a new profile yourself; the menus differ between new and classic Outlook and need review. Record whether send, receive, or both fail only in the app.', 'outlook', 'needs_review'),
  topic('outlook-delayed-mail', 'رسائل البريد تصل متأخرة', 'Email arrives late', 'email', 'Outlook', '', 'بريد متأخر تأخير وصول delay mail late', 'email delayed late arrival', 'قارن وقت الإرسال الظاهر بوقت الوصول على أكثر من رسالة. تحقق من الاتصال قبل افتراض عطل في الخادم. لا تفرّغ صندوق الصادر. إذا تأخر بريد القسم كله، سجّل مثالًا واحدًا بعنوان الوقت واطلب الدعم بدل فتح بلاغات مكررة.', 'Compare the shown send time with the arrival time on more than one message. Check the connection before assuming a server fault. Do not empty the outbox. If a whole department’s mail is late, record one example with the time and ask support instead of opening duplicates.'),
  topic('outlook-shared-calendar', 'التقويم المشترك لا يعرض التحديثات', 'A shared calendar does not show updates', 'email', 'Outlook', '', 'تقويم مشترك لا يتحدث shared calendar', 'shared calendar not updating', 'تأكد أنك فتحت التقويم المشترك الصحيح وأن لديك إذن العرض. اطلب من المالك إرسال تحديث للاجتماع بدل تعديل موعد لا تملكه. لا تزل إذن الزملاء. إذا بقي التقويم قديمًا بعد إعادة فتح Outlook، سجّل اسم التقويم للدعم.', 'Confirm you opened the correct shared calendar and that you have view permission. Ask the owner for an update instead of changing a meeting you do not own. Do not remove colleagues’ permissions. If it stays stale after reopening Outlook, give support the calendar name.'),
  topic('outlook-reminder-missing', 'تذكير اجتماع Outlook لا يظهر', 'An Outlook meeting reminder does not appear', 'email', 'Outlook', '', 'تذكير اجتماع outlook reminder notification', 'outlook meeting reminder missing', 'تحقق أن الاجتماع ما زال في تقويمك وأن التذكير ليس مغلقًا داخل الدعوة نفسها. راجع وضع التركيز أو عدم الإزعاج في النظام دون تعطيل تنبيهات الأمان. لا تغيّر سياسة التنبيهات للجهاز كله. إذا غابت تذكيرات كل الاجتماعات، اذكر ذلك للدعم.', 'Check that the meeting is still on your calendar and that the reminder is not turned off on that item. Review Focus or Do Not Disturb without turning off security alerts. Do not change notification policy for the whole device. If every meeting reminder is missing, tell support.'),
  topic('outlook-distribution-list', 'رسالة إلى مجموعة بريدية لا تصل', 'Mail to a distribution list does not arrive', 'email', 'Outlook', '', 'مجموعة بريدية قائمة توزيع distribution list', 'distribution list group mail not delivered', 'تأكد من اسم المجموعة الكامل وأنك ترسل من حساب العمل. لا تضف العناوين الشخصية كحل. اطلب من عضو واحد في المجموعة التأكد من وصول نسخة. إذا كنت خارج المجموعة أو كانت مقيدة، فهذه صلاحية يراجعها الدعم ولا تُمنح من المحادثة.', 'Confirm the full group name and that you send from the work account. Do not add personal addresses as a workaround. Ask one member whether a copy arrived. If you are outside the group or it is restricted, support reviews that permission; this chat cannot grant it.', 'outlook', 'reviewed', true),
  topic('outlook-undo-send', 'الرغبة في التراجع عن إرسال رسالة', 'Wanting to undo a sent message', 'email', 'Outlook', '', 'تراجع إرسال الغاء ارسال undo send recall', 'undo send recall message', 'التراجع عن الإرسال غير مضمون وقد لا يتوفر في كل الحسابات. لا تفترض أن المستلم لم يقرأ الرسالة. إذا كانت الرسالة تحوي بيانات حساسة فبلّغ الدعم أو الأمن فورًا عبر قناة رسمية، ولا ترسل الرسالة مرة أخرى مع السر. لا تعد المستلم بالحذف.', 'Undo send is not guaranteed and is not available on every account. Do not assume the recipient has not read it. If the message contained sensitive data, tell support or security at once through an official channel, and do not send the secret again. Do not promise the recipient that it was deleted.'),
  topic('teams-echo', 'صدى الصوت في اجتماع Teams', 'Echo during a Teams meeting', 'software', 'Teams', '', 'تيمز صدى صوت echo teams', 'teams echo audio feedback', 'استخدم سماعة واحدة وأبقِ صوت الجهاز الآخر مكتومًا إذا كان الاجتماع مفتوحًا عليه أيضًا. اختر مكبر الصوت نفسه الذي تستخدمه داخل Teams. لا تثبّت أداة صوت خارجية. إذا استمر الصدى مع سماعة واحدة، اذكر نوع السماعة للدعم.', 'Use one headset, and mute the other device if the meeting is open there too. Select that same speaker inside Teams. Do not install an extra audio tool. If the echo continues with one headset, tell support which headset it is.'),
  topic('teams-share-computer-sound', 'مشاركة شاشة Teams من غير صوت الحاسوب', 'Teams screen sharing has no computer sound', 'software', 'Teams', '', 'تيمز مشاركة صوت الحاسوب share sound computer', 'teams share computer sound silent', 'عند المشاركة اختر تضمين صوت الحاسوب إذا كان الخيار ظاهرًا ومسموحًا. تأكد أن المقطع ليس مكتومًا على جهازك. لا تشارك الشاشة كاملة إذا كان يكفي نافذة واحدة. إذا لم يظهر خيار الصوت، سجّل ذلك للدعم لأن توفره يختلف حسب تطبيق Teams.', 'When sharing, include computer sound if that choice is visible and allowed. Confirm the clip is not muted on your device. Do not share the whole screen when one window is enough. If the sound option is missing, tell support; it depends on the Teams app.', 'teams', 'needs_review'),
  topic('teams-chat-not-sending', 'رسالة دردشة Teams لا تُرسل', 'A Teams chat message will not send', 'software', 'Teams', '', 'تيمز دردشة لا ترسل chat not sending', 'teams chat message will not send', 'تحقق من الاتصال ومن أنك داخل حساب العمل. لا تكرر اللصق إذا كانت الرسالة طويلة جدًا؛ قصّها أو أرسل الملف بطريقة المشاركة المعتمدة. لا تنقل المحادثة إلى حساب شخصي. سجّل هل الرسالة تبقى معلقة أم تظهر خطأ.', 'Check the connection and that you are in the work account. Do not keep pasting a very long message; shorten it or share the file through the approved method. Do not move the chat to a personal account. Note whether the message stays pending or shows an error.'),
  topic('teams-notifications-off', 'تنبيهات Teams لا تظهر', 'Teams notifications do not appear', 'software', 'Teams', '', 'تيمز تنبيه إشعار notification missing', 'teams notifications not appearing', 'تحقق من وضع التركيز على الجهاز ومن أن Teams ليس مكتومًا لفترة قصيرة اخترتها. لا تعطّل تنبيهات النظام كلها. إذا كانت القناة مهمة للعمل وما زال التنبيه غائبًا، اذكر اسم القناة للدعم دون نسخ محتوى المحادثة.', 'Check Focus on the device and whether you snoozed Teams. Do not turn off all system notifications. If a work channel still never alerts you, give support the channel name without copying the chat.'),
  topic('teams-status-stuck', 'حالة Teams تبقى مشغولًا', 'Teams status stays Busy', 'software', 'Teams', '', 'تيمز حالة مشغول busy status presence', 'teams status stuck busy presence', 'أغلق الاجتماع المنتهي إذا بقي ظاهرًا، ثم راجع الحالة التي اخترتها يدويًا. لا تخرج من الحساب لإصلاح الحالة. إذا بقيت مشغولًا بعد إغلاق كل الاجتماعات، اذكر ذلك للدعم.', 'Close a finished meeting if it is still showing, then review a status you set manually. Do not sign out of the account just to reset presence. If you stay Busy after every meeting is closed, tell support.'),
  topic('zoom-passcode', 'Zoom يطلب رمز الاجتماع', 'Zoom asks for a meeting passcode', 'software', 'Zoom', '', 'زوم رمز مرور اجتماع passcode zoom', 'zoom meeting passcode required', 'استخدم الدعوة الرسمية من المنظّم ولا تبحث عن الرمز في رسالة مجهولة. لا تنشر الرمز في قناة عامة. إذا لم يصل الرمز مع الدعوة، اطلبه من المنظّم عبر قناة تعرفها. لا تثبّت نسخة Zoom من مصدر غير معتمد.', 'Use the organizer’s official invitation and do not look for the code in an unknown message. Do not post the code in a public channel. If the invitation did not include it, ask the organizer through a channel you already know. Do not install Zoom from an unapproved source.'),
  topic('zoom-muted-audio', 'صوت Zoom لا يعود بعد إلغاء الكتم', 'Zoom audio does not return after unmute', 'software', 'Zoom', '', 'زوم كتم صوت لا يعود unmute audio', 'zoom unmute no audio', 'اختر جهاز الإدخال داخل Zoom نفسه، وتأكد أن كتم النظام غير مفعّل. أغلق تطبيقًا آخر يستخدم الميكروفون. لا تعطِ Zoom صلاحيات أوسع من الصوت. إذا بقي المؤشر يتحرك من غير أن يسمعك الآخرون، اذكر الجهاز المستخدم.', 'Select the input device inside Zoom and confirm the system mute is off. Close another app that is using the microphone. Do not grant Zoom permissions beyond audio. If the meter moves but others still cannot hear you, name the device.'),
  topic('zoom-join-browser', 'الدخول إلى Zoom من المتصفح', 'Joining Zoom from the browser', 'software', 'Zoom', '', 'زوم متصفح بدل التطبيق join browser', 'zoom join from browser', 'إذا كان تطبيق Zoom المعتمد غير متاح، استخدم رابط الدعوة الرسمي في متصفح العمل. لا تثبّت إضافة غير معروفة. تأكد من إذن الميكروفون للمتصفح فقط أثناء الاجتماع. إذا رفضت الشركة الدخول من المتصفح، توقف واطلب التطبيق المعتمد.', 'If the approved Zoom app is unavailable, use the official invite link in the work browser. Do not install an unknown extension. Allow the microphone for the browser only during the meeting. If the company does not allow browser join, stop and ask for the approved app.'),
  topic('teams-recording-unavailable', 'تسجيل اجتماع Teams غير متاح', 'Teams meeting recording is unavailable', 'software', 'Teams', '', 'تيمز تسجيل اجتماع recording unavailable', 'teams recording not available', 'التسجيل يعتمد على دورك ونوع الاجتماع وسياسة الشركة، ومكان الزر يختلف بين إصدارات Teams. لا تستخدم أداة تسجيل خارجية لتجاوز المنع. اطلب من المنظّم التسجيل إذا كانت السياسة تسمح. لا تعد الزملاء بأن التسجيل تم.', 'Recording depends on your role, the meeting type, and company policy, and the button differs between Teams versions. Do not use an outside recorder to bypass a block. Ask the organizer to record if policy allows. Do not tell colleagues a recording exists when it does not.', 'teams', 'needs_review', true),
  topic('meeting-time-zone', 'موعد الاجتماع يظهر بوقت غير صحيح', 'A meeting shows the wrong time', 'email', 'Outlook', '', 'فرق توقيت اجتماع وقت خاطئ timezone', 'meeting wrong time zone', 'قارن المنطقة الزمنية في جهازك مع منطقة جدول العمل. لا تغيّر ساعة الجهاز لتوافق اجتماعًا واحدًا إذا كان ذلك يخالف إعداد الشركة. أخبر المنظّم بالوقت الذي تراه. إذا كانت كل المواعيد منزاحة بالساعات نفسها، سجّل المنطقة الظاهرة للدعم.', 'Compare the device time zone with your work schedule. Do not change the device clock for one meeting if that conflicts with company setup. Tell the organizer the time you see. If every appointment is shifted by the same hours, record the shown zone for support.'),
  topic('word-wont-save', 'Word لا يحفظ التعديلات', 'Word will not save changes', 'software', 'Word', '', 'وورد لا يحفظ save word', 'word will not save', 'احفظ نسخة باسم جديد في مجلد عمل تملك الكتابة فيه، إذا سمح التطبيق بذلك، دون استبدال ملف زميل. تحقق أن الملف ليس للعرض فقط. لا تحذف ملف الاسترداد التلقائي. إذا ظهر أن المجلد للعرض فقط، اطلب صلاحية الكتابة من مالكه.', 'Save a copy under a new name in a work folder you can write to, if the app allows it, without replacing a colleague’s file. Check whether the file is read-only. Do not delete the AutoRecover file. If the folder is view-only, ask its owner for write access.'),
  topic('word-protected-view', 'Word يفتح المستند في طريقة العرض المحمية', 'Word opens a document in Protected View', 'software', 'Word', '', 'وورد عرض محمي protected view', 'word protected view', 'طريقة العرض المحمية مقصودة للملفات القادمة من البريد أو الإنترنت. لا تفعّل التحرير إذا كان المرسل غير معروف أو طلب تفعيل الماكرو. للملف المتوقع من زميل، استخدم خيار التمكين فقط بعد التأكد من المصدر. لا تغيّر إعداد الحماية العام.', 'Protected View is intentional for files from mail or the internet. Do not enable editing if the sender is unknown or the file asks for macros. For an expected file from a colleague, enable editing only after you trust the source. Do not change the general protection setting.'),
  topic('excel-read-only', 'ملف Excel يفتح للقراءة فقط', 'An Excel file opens as read-only', 'software', 'Excel', '', 'اكسل قراءة فقط read only excel', 'excel read only', 'تحقق هل الملف مفتوح عند شخص آخر أو محفوظ في مجلد بلا إذن كتابة. احفظ نسخة للعمل إذا كنت تحتاج تعديلًا مؤقتًا، ولا تستبدل الأصل. لا تغيّر خصائص الملف القادمة من مكتبة مشتركة. اطلب من المالك إغلاق النسخة أو منح التحرير.', 'Check whether someone else has the file open or the folder has no write permission. Save a working copy if you need a temporary edit, and do not replace the original. Do not change file properties on a shared library. Ask the owner to close their copy or grant edit access.'),
  topic('excel-formula-text', 'معادلة Excel تظهر كنص', 'An Excel formula shows as text', 'software', 'Excel', '', 'اكسل معادلة نص formula text apostrophe', 'excel formula shows as text', 'تحقق أن الخلية ليست منسقة كنص وأن المعادلة تبدأ بعلامة يساوي. لا تحوّل الورقة كلها إلى نص. إذا كانت علامة اقتباس قبل المعادلة فاحذفها فقط من تلك الخلية بعد أخذ نسخة. لا تعِد حساب ملف مشترك بطريقة تغيّر أرقام الزملاء قبل الاتفاق.', 'Check that the cell is not formatted as text and that the formula starts with an equals sign. Do not convert the whole sheet to text. If an apostrophe precedes the formula, remove it only from that cell after you keep a copy. Do not recalculate a shared file in a way that changes colleagues’ numbers without agreement.'),
  topic('excel-large-slow', 'ملف Excel كبير وبطيء', 'A large Excel file is slow', 'software', 'Excel', '', 'اكسل بطيء ملف كبير slow workbook', 'excel large file slow', 'أغلق المصنفات الأخرى واحفظ عملك. لا تحذف أوراقًا لا تملكها لتسريع الملف. قلّل الصور المنسوخة داخل الملف إذا كانت من عملك. إذا توقف الملف عند الفتح لأكثر من وقت معقول، سجّل حجمه ومكانه للدعم دون رفع بيانات حساسة.', 'Close other workbooks and save your work. Do not delete sheets you do not own to speed the file up. Reduce pictures you pasted into your own file. If it hangs on open, record its size and location for support without uploading sensitive data.'),
  topic('powerpoint-fonts', 'خطوط PowerPoint تتبدل على جهاز آخر', 'PowerPoint fonts change on another computer', 'software', 'PowerPoint', '', 'بوربوينت خط يتغير fonts missing', 'powerpoint fonts change missing', 'استخدم الخطوط المعتمدة المتاحة على أجهزة العمل. لا تثبّت خطًا شخصيًا من موقع مجهول. راجع الشرائح على الجهاز الذي ستعرض منه. إذا كان الخط جزءًا من قالب الشركة وما زال يتبدل، أرسل اسم الخط للدعم.', 'Use approved fonts that are available on work devices. Do not install a personal font from an unknown site. Review the slides on the computer you will present from. If a company-template font still changes, send its name to support.'),
  topic('powerpoint-slideshow', 'عرض PowerPoint لا يبدأ', 'A PowerPoint slideshow will not start', 'software', 'PowerPoint', '', 'بوربوينت عرض لا يبدأ slideshow', 'powerpoint slideshow will not start', 'تأكد أن الملف يحتوي شرائح وأنك لم تفتح نسخة للقراءة من بريد يمنع التشغيل. جرّب بدء العرض من الشريحة الحالية. لا تعطّل حماية الملفات لتشغيل عرض مجهول. إذا كان جهاز العرض لا يُظهر الصورة، عالج توصيل الشاشة كمشكلة منفصلة.', 'Confirm the file has slides and that you did not open a mail preview that blocks playback. Try starting from the current slide. Do not turn off file protection to run an unknown presentation. If the projector shows no image, treat the display connection as a separate problem.'),
  topic('pdf-asks-password', 'ملف PDF يطلب كلمة مرور', 'A PDF asks for a password', 'software', 'PDF', '', 'pdf كلمة مرور محمي password protected', 'pdf password protected', 'اطلب كلمة المرور من مرسل الملف عبر قناة تعرفه بها. لا تبحث عن أدوات كسر الحماية ولا ترسل الملف إلى موقع عام. إذا نسيت كلمة ملف أنشأته أنت، فالاسترجاع غير مضمون ويحتاج الدعم. لا تشارك كلمة المرور في هذه المحادثة.', 'Ask the sender for the password through a channel you know. Do not look for cracking tools or upload the file to a public site. If you forgot the password of a file you created, recovery is not guaranteed and needs support. Do not share the password in this chat.', 'm365', 'reviewed', true),
  topic('pdf-partial-print', 'طباعة PDF تخرج ناقصة', 'A PDF prints incompletely', 'software', 'PDF', '', 'pdf طباعة ناقصة صفحات print missing pages', 'pdf print missing pages', 'راجع نطاق الصفحات المختار ومعاينة الطباعة قبل إعادة الطباعة. لا تطبع عشرات النسخ للتجربة. تأكد من اختيار الطابعة وحجم الورق الصحيحين. إذا سقطت صفحات بعينها من ملف سليم على الشاشة، سجّل أرقامها للدعم.', 'Check the selected page range and the print preview before printing again. Do not print dozens of test copies. Confirm the printer and paper size. If specific pages are missing from a file that looks complete on screen, record those page numbers for support.'),
  topic('word-paste-hangs', 'Word يتوقف عند اللصق', 'Word hangs when pasting', 'software', 'Word', '', 'وورد لصق يعلق paste hang', 'word hangs on paste', 'الصق كنص فقط إذا كان المصدر منسقًا بشكل ثقيل وكان ذلك يناسب المستند. لا تلصق محتوى من رسالة مشبوهة. احفظ الملف قبل المحاولة التالية. إذا تكرر التوقف مع اللصق العادي، اذكر مصدر المحتوى للدعم.', 'Paste as text only when the source formatting is heavy and plain text is acceptable. Do not paste content from a suspicious message. Save the file before the next try. If ordinary paste keeps hanging, tell support where the content came from.'),
  topic('windows-update-pending', 'Windows يطلب إعادة التشغيل للتحديث', 'Windows asks for a restart to finish an update', 'software', 'Windows', 'Windows', 'ويندوز تحديث اعادة تشغيل windows update restart', 'windows update restart pending', 'احفظ الملفات المفتوحة ثم أعد التشغيل عندما يناسب عملك. لا تفصل الكهرباء أثناء التحديث ولا تكرر إيقاف الجهاز من زر الطاقة. إذا بقيت رسالة التحديث بعد إعادة تشغيل ناجحة، سجّل رقم الرسالة إن وُجد واطلب الدعم. لا تعِد ضبط الجهاز.', 'Save open files, then restart when your work allows. Do not unplug the device during the update or keep forcing power off. If the update message remains after a successful restart, record any error number and ask support. Do not reset the device.'),
  topic('windows-start-menu', 'قائمة ابدأ في Windows لا تفتح', 'The Windows Start menu will not open', 'software', 'Windows', 'Windows', 'ويندوز قائمة ابدأ لا تفتح start menu', 'windows start menu will not open', 'جرّب ضغط مفتاح Windows مرة واحدة بعد إغلاق النافذة الحالية. لا تحذف ملفات النظام لإصلاح القائمة؛ مسار الإصلاح يختلف حسب إصدار Windows ويحتاج مراجعة. إذا كان شريط المهام كله متجمدًا، احفظ ما يمكن حفظه واطلب الدعم قبل أي إعادة ضبط.', 'Press the Windows key once after closing the current window. Do not delete system files to fix the menu; the repair path depends on the Windows version and needs review. If the whole taskbar is frozen, save what you can and ask support before any reset.', 'windows', 'needs_review'),
  topic('windows-taskbar-missing', 'شريط مهام Windows غير ظاهر', 'The Windows taskbar is not visible', 'software', 'Windows', 'Windows', 'ويندوز شريط المهام مختفي taskbar', 'windows taskbar missing hidden', 'حرّك المؤشر إلى حافة الشاشة التي اعتدت رؤية الشريط فيها؛ قد يكون الإخفاء التلقائي مفعّلًا. لا تغيّر إعدادات العرض العامة إذا كان العرض على شاشة ثانية. إذا لم يظهر الشريط على أي حافة، اطلب الدعم.', 'Move the pointer to the screen edge where the bar usually sits; auto-hide may be on. Do not change the general display setup if you are using a second screen. If the bar appears on no edge, ask support.'),
  topic('windows-bluetooth-pair', 'اقتران جهاز Bluetooth في Windows يفشل', 'Bluetooth pairing fails on Windows', 'hardware', 'Windows', 'Windows', 'ويندوز بلوتوث اقتران bluetooth pair', 'windows bluetooth pairing failed', 'تأكد أن الجهاز الآخر في وضع الإقران وقريب من الحاسوب، وأن Bluetooth مفعّل. لا تحذف كل الأجهزة المقترنة. أعد محاولة جهاز واحد فقط. إذا كان الجهاز ملك الشركة وما زال يفشل، سجّل اسمه للدعم.', 'Confirm the other device is in pairing mode, close to the computer, and that Bluetooth is on. Do not remove every paired device. Retry one device only. If it is company equipment and still fails, record its name for support.'),
  topic('windows-wrong-speaker', 'صوت Windows يخرج من جهاز غير مقصود', 'Windows plays sound through the wrong device', 'hardware', 'Windows', 'Windows', 'ويندوز صوت سماعة خاطئة output device', 'windows wrong speaker output', 'اختر جهاز الإخراج من إعداد الصوت السريع في شريط المهام، مثل السماعة بدل الشاشة. لا تعطّل جهاز الصوت. أغلق تطبيق الاجتماع وأعد فتحه بعد اختيار الجهاز. إذا عاد الاختيار الخاطئ كل مرة، اذكر الأجهزة المتصلة.', 'Pick the output device from the quick sound setting on the taskbar, such as the headset instead of the monitor. Do not disable the audio device. Close and reopen the meeting app after the change. If the wrong device returns every time, list the connected devices.'),
  topic('windows-clock-wrong', 'ساعة Windows غير صحيحة', 'The Windows clock is wrong', 'software', 'Windows', 'Windows', 'ويندوز ساعة وقت خاطئ clock time', 'windows clock wrong time', 'فعّل ضبط الوقت التلقائي إذا كان مسموحًا على جهاز العمل، وراجع المنطقة الزمنية لا الساعة فقط. لا تقدم الساعة يدويًا لتجاوز انتهاء ترخيص. إذا أعادت الساعة الخطأ بعد التصحيح، قد يكون الجهاز خارج النطاق ويحتاج الدعم.', 'Turn on automatic time if the work device allows it, and check the time zone as well as the clock. Do not set the clock ahead to bypass a license expiry. If the wrong time returns, the device may be out of sync and needs support.'),
  topic('windows-explorer-slow', 'مستكشف الملفات في Windows بطيء', 'File Explorer is slow on Windows', 'software', 'Windows', 'Windows', 'ويندوز مستكشف الملفات بطيء explorer', 'windows file explorer slow', 'انتظر انتهاء البحث الحالي قبل فتح عدة نوافذ. لا تحذف مجلدات النظام التي تظهر في الوصول السريع. إذا كان البطء عند فتح مجلد شبكة، سجّل مسارًا عامًا من غير بيانات حساسة. لا تثبت أداة تنظيف.', 'Wait for the current search to finish before opening many windows. Do not delete system folders that appear in Quick access. If a network folder is the slow part, record a non-sensitive path. Do not install a cleaner.'),
  topic('windows-notifications', 'إشعارات Windows لا تظهر', 'Windows notifications do not appear', 'software', 'Windows', 'Windows', 'ويندوز إشعارات لا تظهر notifications', 'windows notifications missing', 'راجع وضع التركيز وتأكد أنه ليس في فترة عدم إزعاج اخترتها. لا توقف إشعارات الحماية. اختبر تطبيق عمل واحد فقط. إذا كانت إشعارات ذلك التطبيق وحده غائبة، اذكر اسمه للدعم.', 'Review Focus and confirm you are not in a Do Not Disturb period you set. Do not turn off security notifications. Test one work app. If only that app is silent, give its name to support.'),
  topic('windows-focus-assist', 'وضع التركيز يخفي تنبيهات العمل', 'Focus mode hides work alerts', 'software', 'Windows', 'Windows', 'ويندوز وضع التركيز عدم الازعاج focus assist', 'windows focus assist do not disturb', 'أوقف وضع التركيز مؤقتًا إذا كنت تنتظر تنبيه اجتماع أو دردشة. لا تلغِ تنبيهات الأمان مع إيقاف التركيز. بعد الاجتماع أعد الوضع الذي يناسب المكتب. إذا لم تعرف من فعّل الوضع، اذكر ذلك للدعم.', 'Turn Focus off temporarily if you are waiting for a meeting or chat alert. Do not disable security alerts together with Focus. After the meeting, restore the setting that suits the office. If you do not know who enabled it, tell support.'),
  topic('mac-wifi-work', 'جهاز Mac لا يتصل بشبكة العمل', 'A Mac will not join the work network', 'network', 'macOS', 'macOS', 'ماك واي فاي شبكة العمل mac wifi', 'mac wifi work network', 'اختر شبكة العمل المعتمدة من قائمة Wi-Fi وتأكد أن Wi-Fi مفعّل. لا تحفظ شبكة ضيف بدلها. انسَ الشبكة فقط إذا طلب الدعم ذلك بعد فشل متكرر، لا كخطوة أولى. سجّل اسم الشبكة ورسالة الخطأ.', 'Choose the approved work network from the Wi-Fi menu and confirm Wi-Fi is on. Do not save a guest network instead. Forget the network only if support asks after repeated failure, not as a first step. Record the network name and error.'),
  topic('mac-arabic-input', 'لوحة المفاتيح العربية لا تظهر على Mac', 'Arabic input does not appear on a Mac', 'software', 'macOS', 'macOS', 'ماك لغة عربية كيبورد input source', 'mac arabic keyboard input source', 'أضف مصدر الإدخال العربي من إعدادات لوحة المفاتيح إذا كان الخيار متاحًا لك. بدّل اللغة من مؤشر القائمة لا باختصارات غير معروفة. لا تحذف لغة العمل الإنجليزية إذا كنت تحتاجها. إذا لم يظهر خيار العربية، قد يكون الجهاز مقيّدًا ويحتاج الدعم.', 'Add an Arabic input source from Keyboard settings if you are allowed to. Switch language from the menu indicator, not with unknown shortcuts. Do not remove the work English layout if you still need it. If Arabic is not offered, the device may be managed and needs support.'),
  topic('mac-camera-permission', 'كاميرا Mac مرفوضة لتطبيق الاجتماع', 'A Mac denies the camera to a meeting app', 'software', 'macOS', 'macOS', 'ماك كاميرا اذن privacy camera', 'mac camera permission meeting', 'مكان إذن الكاميرا يختلف بين إصدارات macOS، لذلك لا تتبع مسار قائمة غير مؤكد. أغلق غطاء الكاميرا الفعلي إن وُجد، ثم أعد فتح تطبيق الاجتماع. لا تعطِ الإذن لكل التطبيقات. إذا بقي الرفض، سجّل اسم التطبيق ونسخة النظام للدعم.', 'The camera permission screen differs between macOS versions, so do not follow an unverified menu path. Open the physical camera cover if there is one, then reopen the meeting app. Do not allow every app. If it stays denied, record the app name and system version for support.', 'mac', 'needs_review'),
  topic('mac-update-paused', 'تحديث macOS متوقف', 'A macOS update is stuck', 'software', 'macOS', 'macOS', 'ماك تحديث متوقف macos update stuck', 'macos update stuck', 'أبقِ الجهاز متصلًا بالكهرباء والشبكة وانتظر إذا كان شريط التقدم يتحرك. لا تكرر إطفاء الجهاز. لا تثبت النظام من جديد. إذا لم يتحرك التقدم لوقت طويل أو ظهرت رسالة خطأ، سجّلها واطلب الدعم.', 'Keep the Mac plugged in and on the network, and wait if the progress bar is moving. Do not keep powering it off. Do not reinstall the system. If progress stops for a long time or an error appears, record it and ask support.'),
  topic('mac-finder-disk', 'Finder لا يرى قرصًا أو وحدة تخزين', 'Finder does not see a disk or drive', 'hardware', 'macOS', 'macOS', 'ماك فايندر قرص لا يظهر finder disk', 'mac finder disk not showing', 'تحقق من توصيل الكابل والطاقة من غير شدّ زائد. لا تهيئ القرص فذلك يمسح البيانات. جرّب منفذًا آخر إذا كان مسموحًا. إذا كان القرص ملك الشركة ولم يظهر، توقف واطلب الدعم.', 'Check the cable and power without forcing the connector. Do not erase the disk; that deletes data. Try another allowed port. If it is a company drive and still missing, stop and ask support.'),
  topic('mac-time-machine', 'نسخة Time Machine لا تكتمل', 'A Time Machine backup does not finish', 'software', 'macOS', 'macOS', 'ماك تايم ماشين نسخة time machine backup', 'mac time machine backup failed', 'تأكد أن قرص النسخ المعتمد متصل وأن المساحة ليست ممتلئة. لا تحذف النسخ القديمة بنفسك إذا كانت سياسة الشركة تحتفظ بها. لا تستخدم قرصًا شخصيًا لبيانات العمل. سجّل وقت آخر نسخة ناجحة للدعم.', 'Confirm the approved backup disk is connected and has space. Do not delete old backups yourself if company practice keeps them. Do not use a personal disk for work data. Record the time of the last successful backup for support.', 'mac', 'reviewed', true),
  topic('guest-versus-work-wifi', 'الاتصال بشبكة الضيف بدل شبكة العمل', 'Joined the guest network instead of the work network', 'network', 'Wi-Fi', '', 'شبكة ضيف بدل العمل guest wifi', 'guest wifi instead of work network', 'افصل شبكة الضيف واختر شبكة العمل المعتمدة. لا تطلب كلمة مرور الشبكة في المحادثة. إذا كانت خدمات داخلية لا تفتح وأنت على الضيف، فهذا متوقع غالبًا. بعد التحويل إلى شبكة العمل أعد فتح الخدمة مرة واحدة.', 'Disconnect from the guest network and choose the approved work network. Do not ask for the network password in chat. Internal services often fail on guest Wi-Fi. After you move to the work network, open the service once more.'),
  topic('vpn-certificate-warning', 'تحذير شهادة عند اتصال VPN', 'A certificate warning during VPN connection', 'network', 'VPN', '', 'vpn شهادة تحذير certificate warning', 'vpn certificate warning', 'توقف ولا تتجاوز تحذير الشهادة. تأكد أنك تستخدم عميل VPN المعتمد. لا تثبّت شهادة وصلت بالبريد. سجّل نص التحذير والوقت وأبلغ الدعم أو الأمن.', 'Stop and do not bypass the certificate warning. Confirm you are using the approved VPN client. Do not install a certificate that arrived by email. Record the warning text and time and tell support or security.', 'windows', 'reviewed', true),
  topic('remote-desktop-fails', 'سطح المكتب البعيد لا يتصل', 'Remote desktop will not connect', 'network', 'Remote desktop', '', 'سطح مكتب بعيد remote desktop rdp', 'remote desktop will not connect', 'تأكد من اسم الجهاز كما سلّمه الدعم ومن أن VPN المعتمد متصل إذا كان العمل عن بعد يتطلب ذلك. لا تفتح منافذ على جهازك ولا تستخدم أداة تحكم مجهولة. سجّل نص الخطأ دون صور لبيانات الشاشة.', 'Use the computer name support gave you, and connect the approved VPN if remote work requires it. Do not open ports on your device or use an unknown remote-control tool. Record the error text without screenshots of data.'),
  topic('vpn-internal-sites', 'VPN متصل والمواقع الداخلية لا تفتح', 'VPN is connected but internal sites do not open', 'network', 'VPN', '', 'vpn متصل مواقع داخلية لا تفتح', 'vpn connected internal sites fail', 'تحقق أن العميل يظهر متصلًا ثم جرّب موقعًا داخليًا واحدًا معروفًا. لا تغيّر إعداد الانقسام أو الوكيل. افصل وأعد الاتصال مرة واحدة فقط. إذا استمر المنع، سجّل اسم الموقع والوقت للدعم.', 'Confirm the client shows connected, then try one known internal site. Do not change split-tunnel or proxy settings. Disconnect and reconnect once. If it still fails, record the site name and time for support.'),
  topic('phone-hotspot-temporary', 'استخدام نقطة اتصال الهاتف مؤقتًا', 'Using a phone hotspot temporarily', 'network', 'Wi-Fi', '', 'نقطة اتصال هاتف hotspot مؤقت', 'phone hotspot temporary', 'استخدم نقطة الاتصال الشخصية فقط إذا سمحت الشركة بذلك وعند تعذر شبكة العمل. لا تشارك كلمة نقطة الاتصال في المحادثة. لا تنقل ملفات الشركة إلى تطبيقات الهاتف الشخصية. عند عودة شبكة العمل افصل نقطة الاتصال.', 'Use a personal hotspot only if the company allows it and the work network is down. Do not share the hotspot password in chat. Do not move company files into personal phone apps. Disconnect the hotspot when the work network returns.'),
  topic('wifi-sign-in-page', 'صفحة تسجيل شبكة لا تكتمل', 'A network sign-in page does not finish', 'network', 'Wi-Fi', '', 'صفحة تسجيل واي فاي captive portal', 'wifi sign-in page captive portal', 'افتح المتصفح بعد الاتصال وحاول إكمال صفحة الدخول الرسمية للشبكة. لا تدخل كلمة مرور الحساب في صفحة لا تتطابق مع بوابة الشركة المعروفة. إذا لم تظهر الصفحة، افصل الشبكة وأعد الاتصال مرة واحدة ثم أبلغ الدعم.', 'After connecting, open the browser and try the network’s official sign-in page. Do not enter an account password on a page that does not match the known company portal. If the page never appears, disconnect once and tell support.'),
  topic('username-format', 'اسم المستخدم في شاشة الدخول غير مقبول', 'The sign-in screen rejects the username', 'access', 'Account', '', 'اسم المستخدم صيغة دخول username format', 'username format sign-in rejected', 'راجع صيغة اسم العمل التي تستخدمها عادة، مثل الاسم قبل البريد، دون تجربة كلمات مرور كثيرة. لا تفتح رابط إعادة تعيين من رسالة غير متوقعة. إذا ظهرت رسالة عن اسم المستخدم تحديدًا، انسخ نصها إلى التذكرة واطلب الدعم للتحقق من الهوية.', 'Check the work username format you normally use, such as the name before the email, without trying many passwords. Do not open a reset link from an unexpected message. If the error is specifically about the username, copy that text into a ticket and ask support to verify identity.', 'm365', 'reviewed', true),
  topic('session-keeps-ending', 'جلسة العمل تنتهي بسرعة', 'The work session keeps ending', 'access', 'Account', '', 'جلسة تنتهي خروج متكرر session timeout', 'session keeps signing out timeout', 'لاحظ هل الخروج يحدث بعد مدة محددة أم عند إغلاق المتصفح. لا تحفظ كلمة المرور في متصفح شخصي للالتفاف على الخروج. لا تعطّل مهلة القفل. سجّل التطبيق والمدة التقريبية للدعم.', 'Note whether sign-out happens after a set time or when the browser closes. Do not store the password in a personal browser to avoid it. Do not disable the lock timeout. Record the app and the approximate time for support.'),
  topic('two-work-accounts', 'حسابا عمل على الجهاز نفسه', 'Two work accounts on the same device', 'access', 'Account', '', 'حسابان جهاز واحد two accounts profile', 'two work accounts same device', 'تأكد أي حساب ظاهر في التطبيق قبل إرسال بريد أو ملف. لا تنسخ ملفات من حساب إلى آخر دون إذن. استخدم نافذة أو ملف تعريف منفصلًا إذا كان ذلك متاحًا ومعتمدًا. إذا اختلط التقويمان، اذكر الحسابين للدعم من غير كلمات مرور.', 'Confirm which account is active before you send mail or a file. Do not copy files between accounts without permission. Use a separate window or profile if that is available and approved. If the calendars mixed, tell support the two accounts without passwords.'),
  topic('browser-old-account', 'المتصفح يدخل بحساب قديم', 'The browser signs in with an old account', 'software', 'Browser', '', 'متصفح حساب قديم profile chrome edge', 'browser old account profile', 'اختر ملف تعريف العمل الصحيح من صورة الحساب في المتصفح المعتمد. لا تحذف كل بيانات التصفح. سجّل الخروج من الحساب القديم إذا كان شخصيًا وكنت تعرف أنه لك. إذا كان الحساب لموظف سابق، توقف واطلب الدعم.', 'Choose the correct work profile from the account picture in the approved browser. Do not clear all browsing data. Sign out of an old personal account only if you know it is yours. If the account belongs to a former employee, stop and ask support.'),
  topic('sign-out-all-sessions', 'الرغبة في إغلاق كل جلسات الحساب', 'Wanting to sign out of every session', 'access', 'Account', '', 'تسجيل خروج كل الاجهزة sessions sign out everywhere', 'sign out all sessions devices', 'إغلاق الجلسات البعيدة إجراء أمني ينفذه الفريق المخول أو صفحة الحساب الرسمية إذا كانت معتمدة. لا ترسل كلمة المرور هنا ليقوم أحد بذلك. إذا شككت أن غيرك داخل، بلّغ الدعم فورًا واذكر الأجهزة التي ما زلت تستخدمها.', 'Signing out remote sessions is for the authorized team or an approved account page. Do not send your password here so someone else can do it. If you suspect someone else is signed in, tell support immediately and list the devices you still use.', 'm365', 'reviewed', true),
  topic('login-error-wording', 'رسالة خطأ عند تسجيل الدخول', 'An error appears when signing in', 'access', 'Account', '', 'رسالة خطأ دخول login error text', 'sign-in error message text', 'انسخ نص الخطأ ووقت ظهوره، واذكر هل المشكلة في حساب العمل أم في موقع واحد. لا تجرب كلمات مرور متتالية حتى يُقفل الحساب. لا تشارك الرمز أو كلمة المرور. هذا الوصف يكفي ليفتح الدعم المراجعة.', 'Copy the error text and the time, and say whether it affects the work account or one site. Do not keep trying passwords until the account locks. Do not share a code or password. That description is enough for support to review it.', 'm365', 'reviewed', true),
  topic('print-duplex', 'الطباعة على الوجهين لا تعمل', 'Two-sided printing does not work', 'hardware', 'Printer', '', 'طباعة وجهين duplex two sided', 'duplex two-sided printing', 'راجع خيار الوجهين في نافذة الطباعة قبل إرسال المهمة. لا تطبع الملف عدة مرات على ورق الزملاء. إذا كانت الطابعة لا تدعم الوجهين، اطبع على وجه واحد مؤقتًا. سجّل اسم الطابعة إذا كان الخيار غائبًا رغم أن الجهاز يدعمه.', 'Check the two-sided option in the print window before sending the job. Do not print the file repeatedly onto colleagues’ paper. If the printer cannot duplex, use one side temporarily. Record the printer name if the option is missing on a device that should support it.'),
  topic('print-black-white', 'الطباعة تخرج ملونة دون قصد', 'Printing comes out in color unintentionally', 'hardware', 'Printer', '', 'طباعة ملونة ابيض اسود grayscale', 'color print wanted black and white', 'اختر التدرج الرمادي أو الأبيض والأسود من نافذة الطباعة لتلك المهمة. لا تغيّر الإعداد الافتراضي للطابعة المشتركة إذا كان ذلك يؤثر على القسم. راجع المعاينة. إذا لم يتوفر الخيار، اذكر اسم الطابعة للدعم.', 'Choose grayscale or black and white in the print window for that job. Do not change the default on a shared printer if it affects the department. Check the preview. If the option is missing, give support the printer name.'),
  topic('print-paper-size', 'حجم الورق في الطباعة غير صحيح', 'The printed paper size is wrong', 'hardware', 'Printer', '', 'حجم ورق A4 letter print size', 'paper size A4 letter wrong', 'طابق حجم الصفحة في المستند مع الدرج المختار، مثل A4. لا تسحب الورق من الدرج بقوة. ألغِ مهمتك فقط إذا كانت ما زالت في الانتظار وبإمكانك التعرف عليها. سجّل الحجم المطلوب والظاهر.', 'Match the document page size to the selected tray, such as A4. Do not pull paper out of the tray by force. Cancel only your own job if it is still waiting and you can identify it. Record the size you wanted and the size that printed.'),
  topic('scanner-glass', 'الماسح لا يلتقط الصفحة بوضوح', 'The scanner image is unclear', 'hardware', 'Scanner', '', 'ماسح زجاج غير واضح scanner blur', 'scanner blurry glass', 'تأكد أن الصفحة على الزجاج بالكامل وأن الغطاء مغلق، ونظّف الزجاج من الخارج بقطعة جافة إذا كان ذلك مسموحًا. لا تفك وحدة المسح. احفظ الملف في مجلد العمل وراجع عدد الصفحات. إذا بقي الخط باهتًا، اطلب الدعم.', 'Place the page fully on the glass, close the lid, and wipe the outside of the glass with a dry cloth if that is allowed. Do not open the scanner unit. Save the file in a work folder and check the page count. If the line stays faint, ask support.'),
  topic('display-colors-off', 'ألوان الشاشة مختلفة عن المعتاد', 'Screen colors look wrong', 'hardware', 'Display', '', 'الوان شاشة غريبة night light colors', 'display colors wrong night light', 'عطّل ضوء الليل مؤقتًا إذا كان مفعّلًا وكان اللون أصفر. لا تثبت ملف تعريف لون من الإنترنت. تحقق من كابل الشاشة الخارجية إذا كانت هي المتأثرة فقط. سجّل هل جهاز العرض الداخلي سليم.', 'Turn off night light temporarily if it is on and the screen looks yellow. Do not install a color profile from the internet. Check the external display cable if only that screen is wrong. Note whether the built-in display is fine.'),
  topic('display-low-resolution', 'دقة الشاشة منخفضة والنص كبير', 'The display resolution is low and text is large', 'hardware', 'Display', '', 'دقة شاشة منخفضة resolution scale', 'low resolution large text display', 'اختر الدقة الموصى بها من إعدادات العرض إذا كانت القائمة متاحة لك. لا تستخدم أداة خارجية لتغيير التعريف. إذا كانت الشاشة الخارجية هي منخفضة الدقة فقط، راجع كابلها ومدخلها. اذكر مقاس الشاشة للدعم عند الحاجة.', 'Choose the recommended resolution in display settings if you can open that list. Do not use an outside tool to change the driver. If only the external screen is low resolution, check its cable and input. Tell support the screen size if you need help.'),
  topic('room-projector', 'جهاز عرض قاعة الاجتماع لا يُظهر الصورة', 'A meeting-room projector shows no image', 'hardware', 'Display', '', 'بروجكتر قاعة اجتماع لا يعرض projector', 'meeting room projector no image', 'تأكد من تشغيل جهاز العرض واختيار المدخل الموافق للكابل، ثم اختر تكرار الشاشة من الجهاز. لا تعِد ضبط جهاز القاعة. افصل الكابل وأعد إحكامه مرة واحدة. إذا بقيت الشاشة سوداء، أبلغ الدعم برقم القاعة.', 'Turn the projector on, select the input that matches the cable, then choose duplicate display on the computer. Do not reset the room equipment. Reseat the cable once. If the screen stays black, tell support the room number.'),
  topic('onedrive-file-locked', 'ملف OneDrive مقفل للتحرير', 'A OneDrive file is locked for editing', 'software', 'OneDrive', '', 'ون درايف ملف مقفل locked checked out', 'onedrive file locked checked out', 'انظر هل يظهر اسم الشخص الذي يحرر الملف. لا تنسخ الملف فوق الأصل. اطلب منه إغلاق النسخة أو انتظر. إذا بقي القفل واسم الشخص غير متصل، سجّل اسم الملف للدعم دون فتح صلاحيته بنفسك.', 'See whether the editor’s name is shown. Do not copy a file over the original. Ask that person to close it, or wait. If the lock remains and the person is offline, record the file name for support and do not change its permissions yourself.', 'onedrive', 'reviewed', true),
  topic('sharepoint-browser', 'موقع SharePoint لا يفتح في المتصفح', 'A SharePoint site will not open in the browser', 'software', 'SharePoint', '', 'شيربوينت لا يفتح sharepoint browser', 'sharepoint site will not open', 'جرّب رابط الموقع الرسمي من المفضلة المعتمدة في متصفح العمل. لا تستخدم دعوة من رسالة مجهولة. إذا طلب الموقع حسابًا غير حساب العمل، توقف. سجّل هل الصفحة بيضاء أم تظهر رسالة رفض.', 'Try the official site link from the approved favorites in the work browser. Do not use an invitation from an unknown message. If the site asks for an account other than your work account, stop. Note whether the page is blank or shows Access denied.'),
  topic('sharing-link-expired', 'رابط مشاركة ملف منتهٍ', 'A file sharing link has expired', 'software', 'OneDrive', '', 'رابط مشاركة منتهي expired link', 'sharing link expired', 'اطلب من مالك الملف رابطًا جديدًا أو إذنًا مباشرًا. لا تعِد نشر الرابط القديم. لا تغيّر رابطًا مشتركًا مع أشخاص خارج الشركة إلا وفق السياسة. أرسل اسم الملف لا محتواه الحساس.', 'Ask the file owner for a new link or direct permission. Do not republish the old link. Do not change sharing with people outside the company except under policy. Send the file name, not the sensitive content.'),
  topic('shared-folder-empty', 'مجلد مشترك يظهر فارغًا', 'A shared folder looks empty', 'software', 'SharePoint', '', 'مجلد مشترك فارغ empty library', 'shared folder looks empty', 'تأكد أنك داخل الحساب والمكتبة الصحيحة وأن التصفية ليست مخفية لملفاتك. لا تنشئ المجلد من جديد. حدّث الصفحة مرة واحدة. إذا كان الزملاء يرون الملفات وأنت لا، فهذه صلاحية يراجعها الدعم.', 'Confirm you are in the correct account and library and that a filter is not hiding files. Do not recreate the folder. Refresh the page once. If colleagues can see the files and you cannot, support reviews that permission.', 'sharepoint', 'reviewed', true),
  topic('sync-error-icon', 'أيقونة مزامنة OneDrive تظهر خطأ', 'The OneDrive sync icon shows an error', 'software', 'OneDrive', '', 'مزامنة خطأ ايقونة حمراء sync error', 'onedrive sync error icon', 'افتح مركز المزامنة واقرأ اسم الملف المتعثر دون حذف المجلد المحلي. لا تفصل الحساب. إذا كان الملف باسم غير مسموح أو مسارًا طويلًا، غيّر نسختك أنت فقط بالاتفاق مع المالك. سجّل نص الخطأ للدعم.', 'Open the sync center and read the stuck file name without deleting the local folder. Do not unlink the account. If the name is not allowed or the path is too long, change only your copy after agreeing with the owner. Record the error text for support.'),
  topic('onedrive-recycle', 'استعادة ملف من سلة OneDrive', 'Restore a file from the OneDrive recycle bin', 'software', 'OneDrive', '', 'سلة ون درايف استعادة recycle restore', 'onedrive recycle bin restore', 'ابحث في سلة المحذوفات الخاصة بحساب العمل خلال مدة الاحتفاظ، وأعد الملف إلى مكانه إذا كان لك أو بإذن المالك. لا تفرغ السلة. لا تثبت برنامج استعادة. إذا انتهت المدة فالاسترجاع غير مضمون ويحتاج الدعم.', 'Look in the work account recycle bin during the retention period, and restore the file if it is yours or the owner agrees. Do not empty the bin. Do not install recovery software. If the period has passed, recovery is not guaranteed and needs support.', 'onedrive', 'reviewed', true),
  topic('large-file-upload', 'ملف كبير لا يُرفع', 'A large file will not upload', 'software', 'OneDrive', '', 'ملف كبير رفع فشل upload size', 'large file upload failed', 'استخدم مشاركة الرابط من مجلد العمل بدل إرفاق الملف بالبريد إذا كان الحجم هو السبب. لا تقسّم الملف بأداة مجهولة ولا ترفعه إلى موقع عام. تحقق من المساحة المتبقية. سجّل حجم الملف ومكان الرفع للدعم.', 'Share a link from the work folder instead of attaching the file to email when size is the reason. Do not split it with an unknown tool or upload it to a public site. Check remaining space. Record the size and destination for support.'),
  topic('previous-file-version', 'الحاجة إلى إصدار أقدم من ملف', 'Needing an earlier version of a file', 'software', 'OneDrive', '', 'اصدار سابق ملف version history', 'previous file version history', 'إذا كانت المكتبة تعرض سجل الإصدارات، افتحه واستعد نسخة بعد حفظ الحالية. لا تستبدل ملف الزملاء من غير اتفاق. لا تضمن هذه الخطوة وجود نسخة. إذا لم يظهر السجل، اطلب من الدعم التحقق من مكان الملف.', 'If the library shows version history, open it and restore a copy after saving the current one. Do not replace colleagues’ work without agreement. This step does not guarantee a copy exists. If history is missing, ask support to check where the file lives.'),
  topic('iphone-work-mail', 'إضافة بريد العمل على iPhone', 'Adding work mail on an iPhone', 'email', 'Mail', 'iOS', 'ايفون بريد عمل iphone mail profile', 'iphone work mail profile', 'استخدم تطبيق البريد أو Outlook المعتمد وإجراء تسجيل الجهاز لدى الشركة. لا تضف الحساب إلى تطبيق بريد شخصي غير معتمد ولا توافق على ملف تعريف لا تعرفه. لا تكتب كلمة المرور هنا. إذا لم يكتمل التسجيل، سجّل الخطوة التي توقفت واطلب الدعم.', 'Use the approved Mail or Outlook app and the company’s device enrollment process. Do not add the account to an unapproved personal mail app or accept a profile you do not recognize. Do not type the password here. If enrollment stops, record the step and ask support.', 'iphone', 'reviewed', true),
  topic('android-teams-notify', 'تنبيهات Teams لا تصل على Android', 'Teams notifications do not arrive on Android', 'software', 'Teams', 'Android', 'اندرويد تيمز تنبيه android notification', 'android teams notification missing', 'اسمح بالإشعارات لتطبيق Teams المعتمد من إعدادات التطبيق، وتأكد أن توفير البطارية لا يوقفه. لا تعطّل حماية الجهاز. لا تثبّت نسخة Teams خارج المتجر المعتمد. إذا بقي التنبيه غائبًا، اذكر طراز الجهاز.', 'Allow notifications for the approved Teams app, and check that battery saving is not stopping it. Do not turn off device protection. Do not install Teams from outside the approved store. If alerts stay missing, name the device model.'),
  topic('phone-work-wifi', 'الهاتف لا يدخل شبكة العمل اللاسلكية', 'A phone will not join work Wi-Fi', 'network', 'Wi-Fi', '', 'جوال واي فاي شركة phone wifi', 'phone will not join work wifi', 'اختر الشبكة المعتمدة وانسَ شبكة الضيف إذا اتصلت بها بالخطأ. لا تشارك كلمة الشبكة. قد يتطلب الهاتف تسجيلًا أو شهادة لا تُثبت من رابط بريد. سجّل نوع الهاتف ورسالة الخطأ للدعم.', 'Choose the approved network and forget the guest network if you joined it by mistake. Do not share the network password. The phone may need enrollment or a certificate that you should not install from an email link. Record the phone type and error for support.'),
  topic('phone-os-update', 'تحديث نظام هاتف العمل', 'Updating a work phone operating system', 'hardware', 'Phone', '', 'تحديث نظام جوال مؤسسي os update', 'work phone operating system update', 'ثبّت التحديث من إعدادات الجهاز الرسمية عندما تطلب الشركة ذلك، وبعد الشحن الكافي. لا تكسر حماية الجهاز ولا تستخدم نسخة نظام معدلة. إذا فشل التحديث أو طلب مسح الجهاز، توقف واطلب الدعم قبل المتابعة.', 'Install the update from the official device settings when the company asks, and only with enough charge. Do not jailbreak or root the phone or use a modified system. If the update fails or asks to erase the device, stop and ask support first.', 'iphone', 'reviewed', true),
  topic('payment-request-email', 'رسالة تطلب تحويلًا أو بيانات دفع', 'A message asks for a transfer or payment details', 'access', 'Security', '', 'تحويل مالي تصيد دفع invoice scam', 'payment transfer phishing invoice', 'لا تحوّل مالًا ولا ترسل بيانات حساب بناء على رسالة أو دردشة عاجلة. تحقق من الطالب عبر قناة تعرفه بها مسبقًا. لا تفتح المرفق. بلّغ الأمن بالرسالة عبر القناة المعتمدة واحتفظ بها كدليل دون إعادة توجيهها للزملاء.', 'Do not transfer money or send account details because of an urgent mail or chat. Confirm the requester through a channel you already know. Do not open the attachment. Report the message to security through the approved channel and keep it as evidence without forwarding it to colleagues.', 'm365', 'reviewed', true),
  topic('unexpected-archive', 'مرفق مضغوط غير متوقع', 'An unexpected compressed attachment', 'access', 'Security', '', 'ملف مضغوط zip مرفق غير متوقع', 'unexpected zip attachment', 'لا تفك الضغط ولا تشغّل المحتوى. تأكد عبر قناة أخرى أن المرسل أرسل الملف فعلًا. لا تمرره إلى زميل ليفحصه. بلّغ الأمن إذا كان المرسل غريبًا أو الأسلوب غير معتاد.', 'Do not extract it or run the contents. Confirm through another channel that the sender really sent it. Do not pass it to a colleague to “check”. Tell security if the sender is unknown or the style is unusual.', 'm365', 'reviewed', true),
  topic('unusual-sign-in-alert', 'تنبيه دخول من مكان غير معتاد', 'An alert about a sign-in from an unusual place', 'access', 'Security', '', 'تنبيه دخول غريب unusual sign-in', 'unusual sign-in alert', 'إذا لم تكن أنت من حاول الدخول، بلّغ الدعم أو الأمن فورًا ولا تضغط روابط التنبيه إلا إذا كان من صفحة الحساب الرسمية التي تعرفها. لا ترسل رمز التحقق. اذكر الوقت الظاهر في التنبيه. لا تتجاهل التنبيه.', 'If you did not try to sign in, tell support or security at once and do not use links in the alert unless they are on the official account page you already know. Do not send a verification code. Record the time shown. Do not ignore the alert.', 'm365', 'reviewed', true),
  topic('personal-device-network', 'جهاز شخصي على شبكة العمل', 'A personal device on the work network', 'network', 'Wi-Fi', '', 'جهاز شخصي شبكة العمل byod', 'personal device work network byod', 'لا توصل جهازًا شخصيًا بشبكة العمل إلا إذا كانت السياسة تسمح بذلك. لا تنقل ملفات العمل إلى الجهاز الشخصي للالتفاف على المنع. استخدم شبكة الضيف للتصفح الشخصي إذا كانت متاحة. عند الشك اسأل الدعم قبل الاتصال.', 'Do not put a personal device on the work network unless policy allows it. Do not move work files to a personal device to avoid a restriction. Use guest Wi-Fi for personal browsing if it exists. When unsure, ask support before connecting.'),
  topic('suspicious-qr', 'رمز QR في رسالة أو ملصق غير متوقع', 'An unexpected QR code in a message or poster', 'access', 'Security', '', 'رمز qr مشبوه barcode', 'suspicious qr code', 'لا تفتح رمز QR وصل في رسالة غير متوقعة أو على ملصق لا تعرفه. اكتب عنوان الموقع المعروف يدويًا إذا كنت تحتاج خدمة عمل. لا تدخل بيانات الحساب بعد فتح الرمز. بلّغ الأمن إذا طلب الرمز كلمة مرور.', 'Do not open a QR code from an unexpected message or an unfamiliar poster. Type a known work address yourself if you need a service. Do not enter account details after opening a code. Tell security if the code asks for a password.', 'm365', 'reviewed', true),
  topic('windows-text-size', 'تكبير النص في Windows', 'Making text larger on Windows', 'software', 'Windows', 'Windows', 'ويندوز تكبير نص حجم accessibility scale', 'windows text size accessibility', 'استخدم إعداد حجم النص أو المقياس في إعدادات العرض إذا كان متاحًا. لا تخفض دقة الشاشة فقط لتكبير النص إذا كان ذلك يشوّه الصورة. لا تثبت أداة تكبير مجهولة. إذا كان التكبير لا يشمل تطبيقًا واحدًا، اذكر اسمه.', 'Use text size or scale in display settings if you can. Do not lower the resolution only to enlarge text if that blurs the screen. Do not install an unknown magnifier. If one app ignores the size, name it.'),
  topic('screen-reader-work', 'استخدام قارئ الشاشة مع تطبيقات العمل', 'Using a screen reader with work apps', 'software', 'Accessibility', '', 'قارئ شاشة accessibility إتاحة', 'screen reader accessibility work app', 'استخدم قارئ الشاشة المعتمد على الجهاز. لا تعطّل ميزات الإتاحة لإصلاح تطبيق. إذا كان تطبيق عمل لا يُقرأ بشكل مفهوم، سجّل اسمه والخطوة التي تتوقف عندها واطلب الدعم. لا تطلب تثبيت أداة خارجية غير معتمدة.', 'Use the screen reader provided on the device. Do not turn accessibility features off to “fix” an app. If a work app is not read clearly, record its name and the step where it stops, and ask support. Do not ask for an unapproved external tool.'),
  topic('copy-paste-basics', 'النسخ واللصق لا ينقلان المحتوى', 'Copy and paste do not transfer the content', 'software', 'General', '', 'نسخ لصق لا يعمل copy paste', 'copy paste not working', 'حدد المحتوى ثم انسخه من القائمة لا من اختصار غير متأكد إذا اختلف النظام. الصق داخل التطبيق نفسه أولًا للتحقق. لا تلصق كلمات مرور في المحادثة. إذا فشل اللصق بين تطبيقين محددين، اذكر اسميهما.', 'Select the content and copy it from the menu if you are unsure of the shortcut on that system. Paste inside the same app first to test. Do not paste passwords into this chat. If paste fails between two specific apps, name them.'),
  topic('print-any-to-pdf', 'حفظ أي مستند كملف PDF', 'Saving any document as a PDF', 'software', 'PDF', '', 'حفظ pdf طباعة الى ملف print to pdf', 'print to pdf save document', 'استخدم الطباعة إلى PDF أو التصدير من التطبيق المعتمد إذا ظهر الخيار. راجع الصفحات قبل الحفظ واحفظ الملف في مجلد العمل. لا ترفع المستند إلى موقع تحويل عام. إذا لم يظهر الخيار، اطلب الطريقة المعتمدة لنظامك.', 'Use Print to PDF or Export in the approved app if the option is there. Check the pages, then save in a work folder. Do not upload the document to a public converter. If the option is missing, ask for the approved method for your system.'),
  topic('find-file-device', 'البحث عن ملف على الجهاز', 'Finding a file on the device', 'software', 'General', '', 'ابحث عن ملف على الجهاز search file', 'find a file on the device', 'ابحث باسم مختصر في مجلد العمل أو البحث في النظام، ورتب النتائج بالتاريخ. لا تشغّل بحثًا يحذف الملفات المكررة. إذا كان الملف على مجلد شبكة، تأكد من الاتصال أولًا. سجّل المكان الذي تتوقع وجوده فيه.', 'Search by a short name in the work folder or system search, and sort by date. Do not run a tool that deletes duplicates. If the file is on a network folder, connect first. Record where you expected it to be.'),
  topic('compress-to-send', 'ضغط ملفات لإرسالها', 'Compressing files to send them', 'software', 'General', '', 'ضغط ملفات zip للارسال', 'compress zip files to send', 'اضغط الملفات التي تملكها من أداة النظام المعتمدة إذا كان الحجم يمنع الإرسال. لا تضغط ملفات لا تعرفها. شارك الأرشيف من مجلد العمل لا من بريد شخصي. إذا بقي الحجم كبيرًا، استخدم رابط المشاركة بدل المرفق.', 'Compress files you own with the approved system tool when size blocks sending. Do not compress files you do not recognize. Share the archive from a work folder, not personal mail. If it is still large, use a sharing link instead of an attachment.'),
  topic('link-instead-of-attachment', 'إرسال ملف كبير برابط بدل المرفق', 'Sending a large file as a link instead of an attachment', 'email', 'Outlook', '', 'رابط بدل مرفق ملف كبير sharing link', 'share link instead of attachment', 'احفظ الملف في مجلد العمل ثم أدرج رابط المشاركة من التطبيق المعتمد. راجع من يستطيع الفتح قبل الإرسال. لا تجعل الرابط عامًا للإنترنت إلا إذا كانت السياسة تسمح. لا ترفق نسخة ثانية ضخمة في الرسالة نفسها.', 'Save the file in a work folder, then insert the sharing link from the approved app. Check who can open it before you send. Do not make the link public unless policy allows. Do not also attach a huge copy in the same message.'),
  topic('open-mail-attachment-safely', 'فتح مرفق بريد بأمان', 'Opening a mail attachment safely', 'email', 'Outlook', '', 'فتح مرفق بريد بأمان safe attachment', 'open email attachment safely', 'افتح المرفق فقط إذا كنت تتوقع الرسالة وتعرف المرسل. لا تفعّل المحتوى أو الماكرو. إذا طلب الملف كلمة مرور الحساب فتوقف. أغلقه إذا اختلف الامتداد عن الوصف، وأبلغ الأمن عند الشك.', 'Open an attachment only when you expected the message and know the sender. Do not enable content or macros. If the file asks for your account password, stop. Close it if the extension does not match the description, and tell security when unsure.', 'outlook', 'reviewed', true),
  topic('check-mailbox-space', 'معرفة المساحة المتبقية في صندوق البريد', 'Checking remaining mailbox space', 'email', 'Outlook', '', 'مساحة صندوق البريد المتبقية quota check', 'check mailbox quota remaining', 'اعرض معلومات صندوق البريد من التطبيق أو بريد الويب الرسمي لمعرفة المتبقي. لا تحذف رسائل العمل عشوائيًا لتفريغ المساحة. راجع المرفقات الكبيرة التي تملكها. إذا اقتربت المساحة من الحد، اطلب طريقة الأرشفة المعتمدة.', 'View mailbox information in the app or the official web mailbox to see what remains. Do not delete work mail at random to free space. Review large attachments you own. If you are near the limit, ask for the approved archive method.'),
  topic('error-number-only', 'ظهور رقم خطأ من غير شرح', 'Only an error number appears', 'other', 'General', '', 'رقم خطأ من غير شرح error code number', 'error number only no explanation', 'انسخ الرقم والنص المحيط به واسم التطبيق ووقت الظهور. لا تبحث عن أدوات تدّعي إصلاح الرقم تلقائيًا. لا تغيّر إعدادات النظام بسبب رقم لا تفهمه. أرسل هذه المعلومات في التذكرة ليفسرها الدعم.', 'Copy the number, any surrounding text, the app name, and the time. Do not look for tools that claim to fix the number automatically. Do not change system settings because of a code you do not understand. Put those details in a ticket so support can interpret them.'),
  topic('screenshot-by-system', 'لقطة الشاشة تختلف بين Windows وmacOS', 'Screenshots differ on Windows and macOS', 'software', 'General', '', 'لقطة شاشة ويندوز ماك screenshot windows mac', 'screenshot windows versus mac', 'على Windows استخدم أداة القص المعتمدة، وعلى Mac استخدم أداة اللقطة المدمجة إذا كانت متاحة. لا تخلط اختصارات النظامين. أخفِ البيانات الحساسة قبل الإرسال. هذه النسخة تستقبل وصفًا نصيًا، لذا انسخ نص الخطأ أيضًا.', 'On Windows use the approved snipping tool, and on a Mac use the built-in screenshot tool if it is available. Do not mix the shortcuts of the two systems. Hide sensitive data before sending. This version accepts a text description, so also copy the error text.'),
  topic('unresponsive-app-close', 'إغلاق تطبيق لا يستجيب', 'Closing an app that is not responding', 'software', 'General', '', 'برنامج لا يستجيب اغلاق task manager force quit', 'app not responding force quit', 'احفظ الملفات الأخرى أولًا. أغلق التطبيق من نافذة التطبيقات غير المستجيبة في نظامك دون إنهاء النظام كله. لا تكرر إطفاء الجهاز. إذا تكرر التجمد للتطبيق نفسه، سجّل اسمه ووقته.', 'Save other files first. Close the app from your system’s unresponsive-apps window without shutting down the whole system. Do not keep powering the device off. If the same app keeps freezing, record its name and the time.'),
  topic('device-handover', 'تسليم جهاز عمل لموظف آخر', 'Handing a work device to another employee', 'access', 'Device', '', 'تسليم جهاز موظف آخر handover asset', 'hand a work device to another employee', 'لا تسلّم الجهاز مباشرة من غير إجراء الشركة. سجّل الخروج من حسابك واحذف ملفاتك الشخصية فقط، لا ملفات العمل المشتركة. لا تهيئ الجهاز فذلك قد يمسح بيانات مطلوبة. اطلب من الدعم نقل العهدة.', 'Do not hand the device over outside the company process. Sign out and remove only your personal files, not shared work files. Do not erase the device; that can remove data the company needs. Ask support to transfer the asset.', 'windows', 'reviewed', true),
  topic('bluetooth-headset-meeting', 'سماعة Bluetooth لا تُختار في الاجتماع', 'A Bluetooth headset is not selected in the meeting', 'hardware', 'Headset', '', 'سماعة بلوتوث اجتماع headset meeting', 'bluetooth headset not selected in meeting', 'افصل السماعة وأعد إقرانها إذا كانت معتمدة، ثم اخترها داخل تطبيق الاجتماع لا من النظام فقط. لا تحذف أجهزة الإدخال الأخرى. أغلق تطبيقًا ثانيًا يستخدم الميكروفون. إذا لم تظهر السماعة في القائمة، اذكر اسمها.', 'Disconnect and pair the headset again if it is approved, then select it inside the meeting app, not only in the system. Do not remove the other input devices. Close a second app that is using the microphone. If the headset is not in the list, name it.'),
  topic('outlook-shared-mailbox', 'صندوق بريد مشترك لا يظهر في Outlook', 'A shared mailbox does not appear in Outlook', 'email', 'Outlook', '', 'صندوق مشترك outlook shared mailbox', 'shared mailbox missing outlook', 'تأكد أنك تفتح حساب العمل وأن الصندوق أُضيف لك فعلًا. لا تنشئ صندوقًا جديدًا بالاسم نفسه. حدّث قائمة المجلدات مرة واحدة. إذا كان الزملاء يرونه وأنت لا، فهذه صلاحية يراجعها الدعم ولا تُمنح من المحادثة.', 'Confirm you are in the work account and that the mailbox was actually added for you. Do not create a new mailbox with the same name. Refresh the folder list once. If colleagues can see it and you cannot, support reviews that permission; this chat cannot grant it.', 'outlook', 'reviewed', true),
  topic('excel-filter-hidden', 'تصفية Excel تخفي صفوفًا', 'An Excel filter hides rows', 'software', 'Excel', '', 'اكسل تصفية صفوف مخفية filter hidden', 'excel filter hidden rows', 'انظر هل مؤشر التصفية مفعّل في رأس العمود، وأظهر كل القيم إذا كان الملف لك أو بإذن المالك. لا تحذف الصفوف المخفية. امسح التصفية لا البيانات. إذا لم تستطع إظهار الصفوف، سجّل اسم الورقة للدعم.', 'See whether the filter mark is on in the column header, and show all values if the file is yours or the owner agrees. Do not delete the hidden rows. Clear the filter, not the data. If you cannot show the rows, record the sheet name for support.'),
  topic('teams-background', 'خلفية Teams لا تتغير', 'The Teams background will not change', 'software', 'Teams', '', 'تيمز خلفية اجتماع background blur', 'teams background will not change', 'اختر الخلفية أو الضبابية من إعدادات الجهاز أثناء الاجتماع إذا ظهر الخيار. لا تثبّت خلفية من ملف مجهول. إذا كانت الكاميرا أصلًا لا تعمل فابدأ بمشكلة الكاميرا. إذا غاب الخيار، اذكر إصدار Teams للدعم لأن القوائم تختلف.', 'Choose a background or blur from the device settings during the meeting if the option is shown. Do not install a background from an unknown file. If the camera itself is off, start with the camera problem. If the option is missing, tell support the Teams version because the menus differ.', 'teams', 'needs_review'),
  topic('windows-disk-space', 'تحذير امتلاء مساحة القرص في Windows', 'Windows warns that the disk is almost full', 'software', 'Windows', 'Windows', 'ويندوز مساحة القرص ممتلئة disk full', 'windows disk space full warning', 'أغلق الملفات الكبيرة التي تملكها وانقل ما يلزم إلى مجلد العمل إذا كان ذلك مسموحًا. لا تحذف مجلدات النظام ولا مجلد Windows. لا تثبت أداة تنظيف. إذا بقي التحذير بعد نقل ملفاتك، اطلب من الدعم فحص الجهاز.', 'Close large files you own and move what you need to a work folder if that is allowed. Do not delete system folders or the Windows folder. Do not install a cleaner. If the warning remains after you move your own files, ask support to check the device.'),
  topic('vpn-sleep-disconnect', 'VPN ينقطع بعد إسبات الجهاز', 'VPN disconnects after the computer sleeps', 'network', 'VPN', '', 'vpn ينقطع سكون sleep disconnect', 'vpn disconnects after sleep', 'بعد الاستيقاظ أعد اتصال عميل VPN المعتمد مرة واحدة، ثم افتح خدمة داخلية واحدة. لا تغيّر إعداد الإسبات ليبقي الجهاز يعمل دائمًا من غير موافقة. لا تستخدم عميلًا شخصيًا. إذا تكرر الانقطاع في اليوم نفسه، سجّل الأوقات للدعم.', 'After wake, reconnect the approved VPN client once, then open one internal service. Do not change sleep settings to keep the device running without approval. Do not use a personal client. If it drops again the same day, record the times for support.'),
  topic('windows-keyboard-language', 'تبديل لغة الكتابة في Windows', 'Switching the typing language on Windows', 'software', 'Windows', 'Windows', 'ويندوز تبديل لغة كيبورد language bar', 'windows switch keyboard language', 'بدّل اللغة من مؤشر اللغة في شريط المهام إذا كانت العربية والإنجليزية مضافتين. لا تحذف لغة العمل. لا تثبت لوحة مفاتيح من مصدر خارجي. إذا لم تظهر اللغة المطلوبة في القائمة، قد يكون الجهاز مقيّدًا ويحتاج الدعم.', 'Switch from the language indicator on the taskbar if Arabic and English are already added. Do not remove the work language. Do not install a keyboard from an outside source. If the language you need is not in the list, the device may be managed and needs support.')
];
